import{_ as r,o,c as a,a2 as e}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"🚄 旅行记录","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"features/travel.md","filePath":"features/travel.md"}'),l={name:"features/travel.md"};function n(s,t,i,g,d,h){return o(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="🚄-旅行记录" tabindex="-1">🚄 旅行记录 <a class="header-anchor" href="#🚄-旅行记录" aria-label="Permalink to &quot;🚄 旅行记录&quot;">​</a></h1><p>旅行页是 EmuTrain 的主页，也是最核心的功能之一。它让您把每一次乘火车的经历完整留存下来。</p><hr><h2 id="主页行程卡片" tabindex="-1">主页行程卡片 <a class="header-anchor" href="#主页行程卡片" aria-label="Permalink to &quot;主页行程卡片&quot;">​</a></h2><p>当您有已添加的行程时，主页会以卡片形式列出它们，每张卡片展示：</p><ul><li>🚂 <strong>车次号</strong>（如 G1、D301、K27）</li><li>🏁 <strong>上车站 → 下车站</strong></li><li>🕐 <strong>出发时间</strong> 与 <strong>到达时间</strong></li><li>📅 <strong>乘车日期</strong></li></ul><div class="tip custom-block"><p class="custom-block-title">提示</p><p>列车图标与路局图标可在<strong>设置 → 图标显示</strong>中开关。</p></div><hr><h2 id="行程详情" tabindex="-1">行程详情 <a class="header-anchor" href="#行程详情" aria-label="Permalink to &quot;行程详情&quot;">​</a></h2><p>点击任意行程卡片，进入详情页，可查看：</p><ul><li>列车<strong>当前运行状态</strong></li><li><strong>坐席</strong>类型（商务座 / 一等座 / 二等座 / 软卧 / 硬卧 / 硬座等）</li><li><strong>乘车日期</strong></li><li><strong>始发终到</strong>站与所选<strong>区间</strong></li><li>完整<strong>停靠站点列表</strong></li></ul><p>点击右侧的<strong>线路图按钮</strong>，可查看整条线路的走向图，包含所有停靠站点、到发时刻与里程信息。</p><hr><h2 id="添加行程" tabindex="-1">添加行程 <a class="header-anchor" href="#添加行程" aria-label="Permalink to &quot;添加行程&quot;">​</a></h2><p>在主页右下角点击 <strong>＋</strong> 按钮，即可添加新行程：</p><ol><li><strong>输入车次</strong>（如 <code>G1</code>）</li><li>从查询结果中<strong>选择上车站</strong>与<strong>下车站</strong></li><li><strong>选择乘车日期</strong></li><li><strong>填写坐席</strong>信息</li><li>点击<strong>保存</strong></li></ol><p>支持<strong>自定义行程</strong>，手动填写各项信息，适用于普速列车或特殊情况。</p><hr><h2 id="管理行程" tabindex="-1">管理行程 <a class="header-anchor" href="#管理行程" aria-label="Permalink to &quot;管理行程&quot;">​</a></h2><p>在主页右上角菜单中可进行：</p><table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td>按日期排序</td><td>将所有行程按出发时间从早到晚重新排列</td></tr><tr><td>清空所有</td><td>删除全部行程（需二次确认，操作不可撤销）</td></tr></tbody></table><hr><h2 id="线路走向图" tabindex="-1">线路走向图 <a class="header-anchor" href="#线路走向图" aria-label="Permalink to &quot;线路走向图&quot;">​</a></h2><p>在行程详情页点击右侧按钮，可打开<strong>线路走向图</strong>：</p><ul><li>以列表或图形方式显示该车次<strong>全程停靠站点</strong></li><li>标注每站的<strong>到达 / 出发时刻</strong></li><li>支持<strong>显示里程估算</strong>（在设置中开启）</li><li>高亮您的<strong>上车站 → 下车站</strong>区间</li></ul><p>数据来源：<a href="https://rail.moefactory.com/api/trainDetails/queryTrainRoutes" target="_blank" rel="noreferrer">rail.moefactory.com</a></p>',26)])])}const u=r(l,[["render",n]]);export{p as __pageData,u as default};
